    function getFis() {
        $obs = [];
        $currentRangeStart = 9.90; 
        $rangeStep = 0.01; // Incremento decimal
        $eventEmitterRanges = [
            9.90 => 99,
            9.05 => 95,
            8.79 => 93,
            8.58 => 90,
            8.13 => 85,
            7.90 => 80,
            7.60 => 75,
            7.33 => 70,
            7.06 => 65,
            6.77 => 60,
            6.57 => 55,
            6.32 => 50,
            6.13 => 45,
            5.83 => 40,
            5.58 => 35,
            5.23 => 30,
            4.50 => 20,
            4.00 => 15,
            3.60 => 10,
            3.24 => 7,
            2.85 => 5,
            2.50 => 3,
            1.70 => 1,
            0.00 => 1
        ];
        
        // Sort the ranges in descending order for proper checking
        krsort($eventEmitterRanges);
        
        for ($i = 0; $i <= 990; $i++) {
            $currentValue = round($currentRangeStart - ($i * $rangeStep), 2);
            foreach ($eventEmitterRanges as $rangeStart => $newValue) {
                if ($currentValue >= $rangeStart) {
                    $value = number_format((float)$currentValue, 2);
                    $obs["$value"] = $newValue;
                    break;
                }
            }
        }
        return $obs;
    }

